def transform(grid):
    """Complete every sparse colored copy of the shape shown in color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    reference = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not reference:
        return out
    rbase = min(r for r, c in reference)
    cbase = min(c for r, c in reference)
    shape = {(r-rbase, c-cbase) for r, c in reference}
    colors = {v for row in grid for v in row if v not in (1, 4)}
    for color in colors:
        remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        # A sparse drawing of one copy can have gaps; connect pixels up to
        # Chebyshev distance two while keeping distant same-colored objects apart.
        components = []
        while remaining:
            stack = [remaining.pop()]
            component = set(stack)
            while stack:
                r, c = stack.pop()
                nearby = {p for p in remaining
                          if max(abs(p[0]-r), abs(p[1]-c)) <= 2}
                remaining -= nearby
                component |= nearby
                stack.extend(nearby)
            components.append(component)

        for points in components:
            placements = []
            for top in range(h):
                for left in range(w):
                    translated = {(top+dr, left+dc) for dr, dc in shape}
                    if points <= translated:
                        placements.append((top, left, translated))
            if len(placements) == 1:
                for r, c in placements[0][2]:
                    if 0 <= r < h and 0 <= c < w:
                        out[r][c] = color
    return out
